    # SSYT
    def Pack(self, builder):
        if self.ID is not None:
            ID = builder.CreateString(self.ID)
        if self.NAME is not None:
            NAME = builder.CreateString(self.NAME)
        if self.ABBREVIATION is not None:
            ABBREVIATION = builder.CreateString(self.ABBREVIATION)
        if self.DESIGNATIONS is not None:
            DESIGNATIONSlist = []
            for i in range(len(self.DESIGNATIONS)):
                DESIGNATIONSlist.append(builder.CreateString(self.DESIGNATIONS[i]))
            SSYStartDESIGNATIONSVector(builder, len(self.DESIGNATIONS))
            for i in reversed(range(len(self.DESIGNATIONS))):
                builder.PrependUOffsetTRelative(DESIGNATIONSlist[i])
            DESIGNATIONS = builder.EndVector()
        if self.CROSS_IDS is not None:
            CROSS_IDSlist = []
            for i in range(len(self.CROSS_IDS)):
                CROSS_IDSlist.append(self.CROSS_IDS[i].Pack(builder))
            SSYStartCROSS_IDSVector(builder, len(self.CROSS_IDS))
            for i in reversed(range(len(self.CROSS_IDS))):
                builder.PrependUOffsetTRelative(CROSS_IDSlist[i])
            CROSS_IDS = builder.EndVector()
        if self.MORPHOLOGY is not None:
            MORPHOLOGY = builder.CreateString(self.MORPHOLOGY)
        if self.HOST_ID is not None:
            HOST_ID = builder.CreateString(self.HOST_ID)
        if self.FALSE_POSITIVE_REFS is not None:
            FALSE_POSITIVE_REFSlist = []
            for i in range(len(self.FALSE_POSITIVE_REFS)):
                FALSE_POSITIVE_REFSlist.append(builder.CreateString(self.FALSE_POSITIVE_REFS[i]))
